INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z11-q71','nism-5b-z11','An investor invests ₹1,45,000 in an open-ended scheme at an NAV of ₹58.30. With no entry load, the number of units allotted is:','["8453500.000","14500.000","2432.406","2487.136"]',3,'Units = 145000 ÷ 58.30 = 2487.136.',71) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
