INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z17-q60','nism-5b-z17','An investor sells equity-oriented fund units after 18 months with a long-term capital gain of ₹4,75,000 (no other LTCG in the year). As per the rates in the current workbook, the LTCG tax (ignoring cess) is:','["₹70,000","₹95,000","₹43,750","₹59,375"]',2,'Taxable = 475000 − 1,25,000; tax at 12.5% = ₹43,750.',60) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z17-q61','nism-5b-z17','Employees of institutional distributors must obtain:','["CAN","OTM","EUIN","SCORES ID"]',2,'EUIN must be quoted in forms.',61) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z17-q62','nism-5b-z17','A SIP Top-up of +10% a year on ₹2,500 gives an instalment in year 2 of:','["₹3,000","₹2,510","₹2,750","₹2,600"]',2,'2,500 × 1.10 = 2,750.',62) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z17-q63','nism-5b-z17','Which payment mode is NOT accepted for mutual fund purchases?','["UPI","Debit cards","Credit cards","NEFT"]',2,'Debit cards and net banking are accepted; credit cards are not.',63) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z17-q64','nism-5b-z17','The Trust Deed of a mutual fund must be registered under the:','["Indian Registration Act, 1908","Banking Regulation Act, 1949","Insurance Act, 1938","Companies Act, 2013"]',0,'The Trust Deed is registered under the Indian Registration Act, 1908.',64) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z17-q65','nism-5b-z17','Balanced Hybrid funds hold equity of:','["40–60%, debt 40–60%, with no arbitrage","10–25%","≥65%","65–80%"]',0,'Balanced hybrid: equity 40–60%, debt 40–60%.',65) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z17-q66','nism-5b-z17','A change in Base Expense Ratio must be communicated to investors at least ___ in advance.','["1 day","1 week","3 working days","30 days"]',2,'By email/SMS and a website notice.',66) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z17-q67','nism-5b-z17','An investor invests ₹1,53,000 in an open-ended scheme at an NAV of ₹42.60. With no entry load, the number of units allotted is:','["3591.549","15300.000","3512.518","6517800.000"]',0,'Units = 153000 ÷ 42.60 = 3591.549.',67) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
