INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z17-q69','nism-5b-z17','For a Direct plan the ARN box on the application form should carry:','["The AMC''s code","The word \"Direct\"","It is left blank","The RTA code"]',1,'For Regular plans the ARN/RIA number is written.',69) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z17-q70','nism-5b-z17','The law under which mis-selling is addressed is the:','["Contract Act","SEBI (PFUTP) Regulations, 2003","Companies Act","Negotiable Instruments Act"]',1,'Prohibition of Fraudulent and Unfair Trade Practices.',70) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z17-q71','nism-5b-z17','The I-Bex sub-indices Si-Bex, Mi-Bex and Li-Bex refer to maturities of:','["Up to 1 year, 1–5 years and 5–10 years","1–3 years, 3–7 years and over 7 years","1–2, 2–4 and 4–6 years","0–91 days, 91–365 days and above"]',1,'They are ICICI Securities indices.',71) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z17-q72','nism-5b-z17','A fund returned 15% with a standard deviation of 12%. The risk-free rate is 6%. The Sharpe ratio is:','["1.75","0.64","0.75","1.25"]',2,'Sharpe = (15 − 6) ÷ 12.',72) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z17-q73','nism-5b-z17','Third-party payments for a minor''s investment by parents or related persons are allowed up to:','["₹5,000","Any amount","₹50,000 per purchase or SIP instalment","₹1,00,000"]',2,'A Third Party Declaration and KYC of the payer are required.',73) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z17-q74','nism-5b-z17','Mutual fund portfolios must be disclosed on websites within:','["30 days","10 days of month-end/half-year","3 months","1 year"]',1,'Debt schemes also disclose a fortnightly portfolio within 5 days.',74) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z17-q75','nism-5b-z17','In a joint folio, all benefits (IDCW, redemption proceeds, tax) go to the:','["Youngest holder","All holders equally","First holder","Second holder"]',2,'The folio is in the first holder''s name.',75) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z17-q76','nism-5b-z17','A scheme has an NAV of ₹21.70 and an exit load of 3%. The redemption (repurchase) price per unit is:','["₹18.70","₹21.05","₹21.70","₹22.35"]',1,'Repurchase price = 21.70 × (1 − 3%) = ₹21.05.',76) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z17-q77','nism-5b-z17','A scheme has total assets of ₹499.50 crore, liabilities (other than to unitholders) of ₹8.80 crore and 3.70 crore units outstanding. Its NAV per unit is:','["₹135.00","₹137.38","₹132.62","₹104.40"]',2,'NAV = (499.50 − 8.80) ÷ 3.70 = ₹132.62.',77) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
