INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z17-q80','nism-5b-z17','An investor holds 310 units under the IDCW Reinvestment option. IDCW is ₹1.5 per unit and the ex-IDCW NAV is ₹12. The additional units allotted are:','["77.50","38.75","465.00","34.44"]',1,'Units = (310 × 1.5) ÷ 12 = 38.75.',80) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
