INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z18-q50','nism-5b-z18','A portfolio of ₹20,00,000 is 60:40 equity:debt. Equity rises 10% and debt is unchanged. To rebalance to the original ratio, the amount of equity to be sold is:','["₹1,20,000","₹2,00,000","₹48,000","₹72,000"]',2,'New equity = 1320000; target = 1272000; sell the excess.',50) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
